sections.body:
保存为 cue-memory.mjs，执行 node cue-memory.mjs，无额外依赖。fit 的多数票算法在两版中相同；差别是输入特征。predict 每次扫描一段完整新局，局部变量自然从 unknown 开始，不会继承上一次调用。

```js
/**
 * @file Compare a current-observation classifier with an explicit cue memory.
 * @author liliwei
 * @date 2026-11-23
 * @LastEditors liliwei
 * @LastEditTime 2026-11-23
 */
const tokens = new Set(['red', 'blue', 'blank', 'fork']);
/** @param {string[]} trace One episode ending at a fork. @returns {void} */
function checkTrace(trace) {
  if (!Array.isArray(trace) || trace.length === 0 ||
      trace.at(-1) !== 'fork') throw new Error('Invalid episode');
  for (let i = 0; i < trace.length; i++) {
    if (!tokens.has(trace[i]) || (trace[i] === 'fork' && i !== trace.length - 1))
      throw new Error('Invalid observation');
  }
}
/** @param {string[]} trace Checked episode. @param {boolean} remember Keep cues.
 * @returns {string} Feature available at the fork; no answer label is read. */
function feature(trace, remember) {
  let cue = 'unknown';
  for (const observation of trace) {
    if (observation === 'red' || observation === 'blue') cue = observation;
  }
  return remember ? cue : 'fork';
}
/** @param {{trace:string[],label:string}[]} rows Labeled training episodes.
 * @param {boolean} remember Enable explicit memory. @returns {Map<string,string>} Frozen choices. */
export function fit(rows, remember) {
  if (!Array.isArray(rows) || rows.length === 0 || typeof remember !== 'boolean')
    throw new Error('Invalid training input');
  const counts = new Map();
  for (const row of rows) {
    checkTrace(row?.trace);
    if (!['left', 'right'].includes(row.label)) throw new Error('Invalid label');
    const key = feature(row.trace, remember);
    if (key === 'unknown') throw new Error('Missing training cue');
    const count = counts.get(key) ?? [0, 0];
    count[row.label === 'left' ? 0 : 1]++;
    counts.set(key, count);
  }
  return new Map([...counts].map(([key, [l, r]]) => [key, l >= r ? 'left' : 'right']));
}
/** @param {Map<string,string>} table Trained table, treated as read-only.
 * @param {string[]} trace One new episode. @param {boolean} remember Keep cues.
 * @returns {string|null} Proposed branch, or abstention for unseen features. */
export function predict(table, trace, remember) {
  checkTrace(trace);
  if (!(table instanceof Map) || typeof remember !== 'boolean') throw new Error('Invalid policy');
  return table.get(feature(trace, remember)) ?? null;
}

const train = [1, 2].flatMap(gap => ['red', 'blue'].map(cue => ({
  trace: [cue, ...Array(gap).fill('blank'), 'fork'],
  label: cue === 'red' ? 'left' : 'right'
})));
export const reactive = fit(train, false), memory = fit(train, true);
export const results = [0, 3, 7].map(gap => {
  const tests = ['red', 'blue'].map(cue => ({
    trace: [cue, ...Array(gap).fill('blank'), 'fork'],
    label: cue === 'red' ? 'left' : 'right'
  }));
  return { gap, total: tests.length,
    reactive: tests.filter(x => predict(reactive, x.trace, false) === x.label).length,
    memory: tests.filter(x => predict(memory, x.trace, true) === x.label).length };
});
console.log(JSON.stringify({ reactive: [...reactive], memory: [...memory], results,
  noCue: predict(memory, ['blank', 'fork'], true) }));
```

这是离线序列检查器，每次预测会扫描整段 trace；它不是应在每一渲染帧重复调用的生产组件。真实运行时可逐个处理观测，维护一个 cue 字段，并显式实现 beginEpisode。表虽按约定冻结，JavaScript Map 本身仍可修改，调用方不能在评估期间继续训练。
